+        let app = ensure_app(temp.path()).unwrap();
+        assert!(Command::new(executable(&app)).arg("--check").status().unwrap().success());
+        assert!(Command::new("/usr/bin/codesign").args(["--verify", "--strict"]).arg(&app).status().unwrap().success());
+        assert_eq!(ensure_app(temp.path()).unwrap(), app);
+    }
+}
