+fn retain_omitted(
+    repo: &HistoryRepo,
+    tree: &str,
+    previous: Option<(&Checkpoint, &str)>,
+    tracked: &TrackedSet,
+    omissions: &[&store::PathReason],
+    modes: &mut BTreeMap<String, u32>,
